void Instance::predelete()
{
	// rebuild overlay: release the children so none keeps a dangling parent
	if (children) {
		std::vector<shared_ptr<Instance> > copy(*children);
		for (size_t i = 0; i < copy.size(); ++i) {
			copy[i]->setParent(NULL);
		}
	}
}
